lines<-readLines("stdin",warn=FALSE);n<-as.integer(lines[1]);ok<-function(x){if(grepl("[^PAT]",x)||length(gregexpr("P",x,fixed=TRUE)[[1]])!=1||length(gregexpr("T",x,fixed=TRUE)[[1]])!=1)return(FALSE);p<-regexpr("P",x,fixed=TRUE);t<-regexpr("T",x,fixed=TRUE);a<-p-1L;b<-t-p-1L;c<-nchar(x)-t;b>0L&&a*b==c};cat(paste(ifelse(vapply(lines[2:(n+1L)],ok,logical(1)),"YES","NO"),collapse="\n"),"\n")
